"""Native exact-type capture of publication measurements.

The request is an owned typed value, not a caller's validation assertion.
Strings carry all Python Unicode code points, including lone surrogates.
The existing publication_measurement numerical policy is unchanged.
"""
from pathlib import Path
import re
from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_system_jobctl_request import document
ROOT=Path(__file__).resolve().parents[1]
POLICY="def measurement_typed(s:readbuf,o:mutbuf,w:mutbuf) -> u32:\n    if length(s)<64 or length(w)<65536 or word(s,0)!=REQUEST:\n        return BAD\n    rootn=word(s,8)\n    sign=word(s,16)\n    n=word(s,24)\n    if rootn>length(s)-64 or n!=length(s)-64-rootn or sign>1:\n        return BAD\n    i=32\n    while i<64:\n        if word(s,i)!=0:\n            return BAD\n        i=i+8\n    if (n==0 and sign!=0) or (n!=0 and byte(s,length(s)-1)==0):\n        return BAD\n    root=64\n    end=64+rootn\n    if node_end(s,root,end)!=end:\n        return BAD\n    zero(w,0,4096)\n    put(w,16,end)\n    put(w,24,sign)\n    put(w,32,n)\n    if word(s,root)!=7 or word(s,root+8)<8 or word(s,root+16)!=12:\n        return failure(o,w,1)\n    at=root+24\n    i=0\n    while i<12:\n        keyend=node_end(s,at,end)\n        if keyend==NONE:\n            return BAD\n        key=label(s,at)\n        if key==0 or get(w,128+key*8)!=0:\n            return failure(o,w,1)\n        value=keyend\n        valueend=node_end(s,value,end)\n        if valueend==NONE:\n            return BAD\n        put(w,128+key*8,value)\n        at=valueend\n        i=i+1\n    if at!=end:\n        return BAD\n    i=1\n    while i<=12:\n        if get(w,128+i*8)==0:\n            return failure(o,w,1)\n        i=i+1\n    if text_is(s,field(w,1),1)==0:\n        return failure(o,w,2)\n    i=2\n    while i<=6:\n        if hexadecimal(s,field(w,i))==0:\n            return failure(o,w,i+1)\n        i=i+1\n    node=field(w,7)\n    if word(s,node)!=4 or word(s,node+8)==0 or word(s,node+8)>1024 or (word(s,node+8)&3)!=0:\n        return failure(o,w,8)\n    i=0\n    while i<word(s,node+8):\n        if unit(s,node+16+i)>1114111:\n            return BAD\n        i=i+4\n    i=8\n    while i<=11:\n        low=1\n        high=64000000\n        if i==9:\n            high=1000000000000\n        elif i==10:\n            low=0\n            high=3600000000000\n        elif i==11:\n            high=3600000000000\n        value=integer(s,field(w,i),low,high)\n        if value==NONE:\n            return failure(o,w,i+1)\n        put(w,512+i*8,value)\n        i=i+1\n    samples=field(w,12)\n    if word(s,samples)!=5 or word(s,samples+8)<8:\n        return failure(o,w,13)\n    count=word(s,samples+16)\n    if count<15 or count>63 or (count&1)!=1:\n        return failure(o,w,13)\n    put(w,64,count)\n    at=samples+24\n    end=node_end(s,samples,64+rootn)\n    i=0\n    while i<count:\n        next=node_end(s,at,end)\n        if next==NONE:\n            return BAD\n        if word(s,at)!=7 or word(s,at+8)<8 or word(s,at+16)!=2:\n            return failure(o,w,15)\n        cursor=at+24\n        j=0\n        baseline=0\n        candidate=0\n        while j<2:\n            keyend=node_end(s,cursor,next)\n            if keyend==NONE:\n                return BAD\n            key=pair_label(s,cursor)\n            valueend=node_end(s,keyend,next)\n            if valueend==NONE:\n                return BAD\n            if key==1 and baseline==0:\n                baseline=keyend\n            elif key==2 and candidate==0:\n                candidate=keyend\n            else:\n                return failure(o,w,15)\n            cursor=valueend\n            j=j+1\n        if cursor!=next:\n            return BAD\n        if baseline==0 or candidate==0:\n            return failure(o,w,15)\n        a=integer(s,baseline,1,60000000000)\n        b=integer(s,candidate,1,60000000000)\n        if a==NONE or b==NONE:\n            return failure(o,w,16)\n        put(w,1024+i*16,a)\n        put(w,1032+i*16,b)\n        at=next\n        i=i+1\n    if at!=end:\n        return BAD\n    put(w,0,16384)\n    canonical(s,w)\n    canonical_n=get(w,0)-16384\n    packet_n=208+get(w,64)*16+n\n    if packet_n<208 or packet_n>length(w)-65536:\n        return BAD\n    numeric(s,w)\n    if length(o)<128 or canonical_n>length(o)-128 or packet_n>length(o)-128-canonical_n:\n        return SHORT\n    zero(o,0,128)\n    put(o,0,REPLY)\n    put(o,24,canonical_n)\n    put(o,32,packet_n)\n    put(o,40,get(w,64))\n    copy(o,128,w,16384,canonical_n)\n    copy(o,128+canonical_n,w,65536,packet_n)\n    return 0\n\ndef node_end(s:readbuf,at:u64,end:u64) -> u64:\n    if at>end or end>length(s) or end-at<16:\n        return NONE\n    n=word(s,at+8)\n    if n>end-at-16:\n        return NONE\n    return at+16+n\n\ndef field(w:mutbuf,key:u64) -> u64:\n    return get(w,128+key*8)\n\ndef hexadecimal(s:readbuf,node:u64) -> u64:\n    if word(s,node)!=4 or word(s,node+8)!=256:\n        return 0\n    i=0\n    while i<64:\n        c=unit(s,node+16+i*4)\n        if ((c>=48 and c<=57) or (c>=97 and c<=102))==False:\n            return 0\n        i=i+1\n    return 1\n\ndef integer(s:readbuf,node:u64,low:u64,high:u64) -> u64:\n    if word(s,node)!=2 or word(s,node+8)==0:\n        return NONE\n    n=word(s,node+8)\n    value=0\n    i=0\n    if byte(s,node+16)==45:\n        # Every negative exact integer is outside these original domains.\n        return NONE\n    if n>1 and byte(s,node+16)==48:\n        return NONE\n    while i<n:\n        c=byte(s,node+16+i)\n        if c<48 or c>57:\n            return NONE\n        digit=c-48\n        if value>high//10 or (value==high//10 and digit>high%10):\n            return NONE\n        value=value*10+digit\n        i=i+1\n    if value<low:\n        return NONE\n    return value\n\ndef canonical(s:readbuf,w:mutbuf) -> u64:\n    literal(w,1)\n    ascii_string(s,w,field(w,5))\n    literal(w,2)\n    ascii_string(s,w,field(w,3))\n    literal(w,3)\n    ascii_string(s,w,field(w,4))\n    literal(w,4)\n    ascii_string(s,w,field(w,2))\n    literal(w,5)\n    decimal(w,get(w,576))\n    literal(w,6)\n    ascii_string(s,w,field(w,7))\n    literal(w,7)\n    decimal(w,get(w,584))\n    literal(w,8)\n    decimal(w,get(w,600))\n    literal(w,9)\n    i=0\n    while i<get(w,64):\n        if i!=0:\n            emit(w,44)\n        literal(w,10)\n        decimal(w,get(w,1024+i*16))\n        literal(w,11)\n        decimal(w,get(w,1032+i*16))\n        emit(w,125)\n        i=i+1\n    literal(w,12)\n    ascii_string(s,w,field(w,1))\n    literal(w,13)\n    decimal(w,get(w,592))\n    literal(w,14)\n    ascii_string(s,w,field(w,6))\n    emit(w,125)\n    return 0\n\ndef numeric(s:readbuf,w:mutbuf) -> u64:\n    at=65536\n    zero(w,at,208)\n    put(w,at,NUMERIC)\n    put(w,at+8,get(w,64))\n    put(w,at+16,get(w,576))\n    put(w,at+24,get(w,584))\n    put(w,at+32,get(w,592))\n    put(w,at+40,get(w,600))\n    put(w,at+48,get(w,24))\n    put(w,at+56,get(w,32))\n    i=0\n    before=field(w,4)\n    after=field(w,5)\n    while i<64:\n        store(w,at+80+i,unit(s,before+16+i*4))\n        store(w,at+144+i,unit(s,after+16+i*4))\n        i=i+1\n    i=0\n    while i<get(w,64):\n        put(w,at+208+i*16,get(w,1024+i*16))\n        put(w,at+216+i*16,get(w,1032+i*16))\n        i=i+1\n    i=0\n    while i<get(w,32):\n        store(w,at+208+get(w,64)*16+i,byte(s,get(w,16)+i))\n        i=i+1\n    return 0\n\ndef ascii_string(s:readbuf,w:mutbuf,node:u64) -> u64:\n    emit(w,34)\n    i=0\n    while i<word(s,node+8):\n        cp=unit(s,node+16+i)\n        if cp==34 or cp==92:\n            emit(w,92)\n            emit(w,cp)\n        elif cp==8:\n            emit(w,92)\n            emit(w,98)\n        elif cp==9:\n            emit(w,92)\n            emit(w,116)\n        elif cp==10:\n            emit(w,92)\n            emit(w,110)\n        elif cp==12:\n            emit(w,92)\n            emit(w,102)\n        elif cp==13:\n            emit(w,92)\n            emit(w,114)\n        elif cp>=32 and cp<=126:\n            emit(w,cp)\n        elif cp<=65535:\n            escape(w,cp)\n        else:\n            cp=cp-65536\n            escape(w,55296+(cp>>10))\n            escape(w,56320+(cp&1023))\n        i=i+4\n    emit(w,34)\n    return 0\n\ndef escape(w:mutbuf,cp:u64) -> u64:\n    emit(w,92)\n    emit(w,117)\n    shift=12\n    i=0\n    while i<4:\n        digit=(cp>>shift)&15\n        emit(w,choose(digit<10,48+digit,87+digit))\n        if shift!=0:\n            shift=shift-4\n        i=i+1\n    return 0\n\ndef decimal(w:mutbuf,value:u64) -> u64:\n    n=0\n    again=True\n    while again:\n        store(w,8192+n,48+value%10)\n        n=n+1\n        value=value//10\n        again=value!=0\n    while n!=0:\n        n=n-1\n        emit(w,byte(w,8192+n))\n    return 0\n\ndef emit(w:mutbuf,value:u64) -> u64:\n    at=get(w,0)\n    store(w,at,value)\n    put(w,0,at+1)\n    return 0\n\ndef failure(o:mutbuf,w:mutbuf,code:u64) -> u32:\n    put(w,0,16384)\n    error_text(w,code)\n    n=get(w,0)-16384\n    if length(o)<128 or n>length(o)-128:\n        return SHORT\n    zero(o,0,128)\n    put(o,0,REPLY)\n    put(o,8,1)\n    put(o,16,code)\n    put(o,48,n)\n    copy(o,128,w,16384,n)\n    return 0\n\ndef copy(o:mutbuf,to:u64,w:mutbuf,at:u64,n:u64) -> u64:\n    i=0\n    while i<n:\n        store(o,to+i,byte(w,at+i))\n        i=i+1\n    return 0\n\ndef zero(w:mutbuf,at:u64,n:u64) -> u64:\n    i=0\n    while i<n:\n        store(w,at+i,0)\n        i=i+1\n    return 0\n\ndef unit(s:readbuf,at:u64) -> u64:\n    return readn(s,at,4)\n\ndef word(s:readbuf,at:u64) -> u64:\n    return readn(s,at,8)\n\ndef readn(s:readbuf,at:u64,n:u64) -> u64:\n    value=0\n    i=0\n    while i<n:\n        value=value|(byte(s,at+i)<<(i*8))\n        i=i+1\n    return value\n\ndef get(w:mutbuf,at:u64) -> u64:\n    value=0\n    i=0\n    while i<8:\n        value=value|(byte(w,at+i)<<(i*8))\n        i=i+1\n    return value\n\ndef put(w:mutbuf,at:u64,value:u64) -> u64:\n    i=0\n    while i<8:\n        store(w,at+i,value>>(i*8))\n        i=i+1\n    return 0\n"
KEYS=['schema','before_sha256','after_sha256','before_artifact_sha256','after_artifact_sha256','workload_sha256','function','calls_per_sample','horizon_calls','search_cost_ns','maximum_search_ns','samples']
LITERALS=['{"after_artifact_sha256":',',"after_sha256":',',"before_artifact_sha256":',',"before_sha256":',',"calls_per_sample":',',"function":',',"horizon_calls":',',"maximum_search_ns":',',"samples":[','{"baseline_ns":',',"candidate_ns":','],"schema":',',"search_cost_ns":',',"workload_sha256":']
ERRORS=['measurement requires the exact native-publication envelope','measurement schema is not qualified','measurement has an invalid before_sha256','measurement has an invalid after_sha256','measurement has an invalid before_artifact_sha256','measurement has an invalid after_artifact_sha256','measurement has an invalid workload_sha256','measurement must name one bounded exported function','measurement has an out-of-range exact integer: calls_per_sample','measurement has an out-of-range exact integer: horizon_calls','measurement has an out-of-range exact integer: search_cost_ns','measurement has an out-of-range exact integer: maximum_search_ns','measurement requires 15..63 odd paired samples','measurement sample sequence changed during capture','measurement sample requires exactly baseline_ns and candidate_ns','measurement samples require bounded positive exact nanoseconds']
def labels(name,items):
    lines=[f'def {name}(s:readbuf,node:u64) -> u64:','    if word(s,node)!=4:','        return 0']
    for i,text in enumerate(items,1):
        raw=text.encode('utf-32-le')
        terms=[f'word(s,node+8)=={len(raw)}']+[f'readn(s,node+{16+j},{len(raw[j:j+8])})=={int.from_bytes(raw[j:j+8],"little")}' for j in range(0,len(raw),8)]
        lines+=['    if '+' and '.join(terms)+':',f'        return {i}']
    lines+=['    return 0'];return '\n'.join(lines)
def literals(name,items):
    lines=[f'def {name}(w:mutbuf,which:u64) -> u64:']
    for i,text in enumerate(items,1):
        raw=text.encode('ascii');lines += [f'    if which=={i}:','        at=get(w,0)']
        for j in range(0,len(raw),8):
            part=raw[j:j+8]
            if len(part)==8:lines.append(f'        put(w,at+{j},{int.from_bytes(part,"little")})')
            else:
                for k,c in enumerate(part):lines.append(f'        store(w,at+{j+k},{c})')
        lines += [f'        put(w,0,at+{len(raw)})','        return 0']
    lines += ['    return 0'];return '\n'.join(lines)
def source_program():
    text=POLICY+'\n'+labels('label',KEYS)+'\n'+labels('pair_label',['baseline_ns','candidate_ns'])+'\n'+labels('text_kind',['hepta.hia.native-publication-measurement.v1'])+'\n'+literals('literal',LITERALS)+'\n'+literals('error_text',['E_HIA_MULTIVERSION: '+x for x in ERRORS])
    text += '\ndef text_is(s:readbuf,node:u64,expected:u64) -> u64:\n    return choose(text_kind(s,node)==expected,1,0)\n'
    for k,v in {'REQUEST':int.from_bytes(b'HIAMVMT1','little'),'REPLY':int.from_bytes(b'HIAMVMR1','little'),'NUMERIC':int.from_bytes(b'HIAPME01','little'),'NONE':(1<<64)-1,'BAD':0xfffffffd,'SHORT':0xfffffffe}.items():text=re.sub(r'\b'+k+r'\b',str(v),text)
    return text
def main():
    t=document(source_program(),'multiversion_measurement_typed')
    p=ROOT/'examples/hia_bootstrap/multiversion_measurement_typed.hepta';p.write_text(render_assembly(t))
    print(p.name,p.stat().st_size,len(t['functions']),sum(len(f['blocks']) for f in t['functions']),flush=True)
if __name__=='__main__':main()
